SourceCode.Declaration:
/// <summary>
/// Subscribes to <c>Application.onTtsNotifyCommit</c> and <c>Application.onTtsNotifyAbort</c>
/// so that asynchronous outbound Salesforce HTTP pushes are only dispatched after the outer
/// D365 database transaction commits.
/// </summary>
public class UTCSFPostCommitDispatcher
{
    // Cap per-transaction Global::runAsync fan-out so bulk imports (DMF/OData/CDX)
    // do not exhaust the AOS async thread pool or trigger OAuth2 token stampedes.
    private const int      MaxImmediateAsyncFanOut = 5;
    private static Set     pendingQueueRecIds;
    private static boolean isSubscribed;

}

Method.Source:
/// <summary>
/// Registers a <c>UTCSFCustomerPushQueue</c> RecId to be dispatched asynchronously as soon as the current TTS commits.
/// </summary>
/// <param name = "_queueRecId">RecId of the staging queue item.</param>
public static void registerQueueItemForCommit(RecId _queueRecId)
{
    if (!_queueRecId)
    {
        return;
    }

    if (pendingQueueRecIds == null)
    {
        pendingQueueRecIds = new Set(Types::Int64);
    }

    pendingQueueRecIds.add(_queueRecId);

    if (!isSubscribed)
    {
        appl.onTtsNotifyCommit += eventhandler(UTCSFPostCommitDispatcher::onTtsNotifyCommit);
        appl.onTtsNotifyAbort  += eventhandler(UTCSFPostCommitDispatcher::onTtsNotifyAbort);
        isSubscribed = true;
    }
}

/// <summary>
/// Event handler invoked by the kernel when the outermost transaction commits (<c>ttsLevel == 0</c>).
/// </summary>
public static void onTtsNotifyCommit()
{
    if (pendingQueueRecIds == null || pendingQueueRecIds.empty())
    {
        return;
    }

    Set itemsToDispatch = pendingQueueRecIds;
    pendingQueueRecIds  = new Set(Types::Int64);

    // If a bulk transaction enqueued many records, defer to the scheduled SysOperation batch job
    if (itemsToDispatch.elements() > MaxImmediateAsyncFanOut)
    {
        return;
    }

    SetEnumerator enumerator = itemsToDispatch.getEnumerator();

    while (enumerator.moveNext())
    {
        RecId queueRecId = enumerator.current();
        UTCSFCustomerPushBatchService::triggerImmediateAsyncPush(queueRecId);
    }
}

/// <summary>
/// Clears pending in-memory queue IDs if the transaction rolls back.
/// </summary>
public static void onTtsNotifyAbort()
{
    if (pendingQueueRecIds != null)
    {
        pendingQueueRecIds = new Set(Types::Int64);
    }
}
